window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ecbaf97b32c9bc8b"]={"versions": [{"id": "FIG-ecbaf97b32c9bc8b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstruktur-Spezifikation der E2E-Bibliothek (AUTOSAR Classic Platform). Das Diagramm definiert den Zustandsdatentyp für den Schutzmechanismus des E2E-Profils 7 (<code>E2E Profile 7</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturtyp:</p>\n<ul class=\"fig-list\"><li><code>«structure» E2E::E2E_P07Types::E2E_P07ProtectStateType</code>\n</li></ul>\n<p class=\"fig-p\">Attribute:</p>\n<ul class=\"fig-list\"><li><code>+ Counter :uint32</code>: Öffentliches Attribut zur Speicherung des 32-Bit-Sequenzzählers des Senders für nachfolgende Absicherungsoperationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne dynamische Ablauf- oder Zustandsübergangsdarstellung. Der Typ kapselt den Senderzustand über aufeinanderfolgende Aufrufe der Schutzfunktion <code>E2E_P07Protect</code> hinweg, wobei der enthaltene Sequenzzähler (<code>Counter</code>) pro geschützter Nachricht inkrementiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der C-Struktur für die E2E-Profil-7-Senderzustandsverwaltung. Softwarekomponenten und E2E-Wrapper müssen eine Instanz dieses Typs persistent im RAM vorhalten und als Ein-/Ausgangsparameter an die E2E-Schutzroutine übergeben, um die Sequenzzählung und Erkennung von Nachrichtenwiederholungen/Verlusten sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-360665a0f11f90fd", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstruktur-Spezifikation der E2E-Bibliothek (AUTOSAR Adaptive / Classic Platform). Das Diagramm definiert den Zustandsdatentyp für den Schutzmechanismus des E2E-Profils 7 (<code>E2E Profile 7</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturtyp:</p>\n<ul class=\"fig-list\"><li><code>«structure» E2E_P07Types::E2E_P07ProtectStateType</code>\n</li></ul>\n<p class=\"fig-p\">Attribute:</p>\n<ul class=\"fig-list\"><li><code>+ Counter: uint32</code>: Öffentliches Attribut zur Speicherung des 32-Bit-Sequenzzählers des Senders für nachfolgende Absicherungsoperationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne dynamische Ablauf- oder Zustandsübergangsdarstellung. Der Typ kapselt den Senderzustand über aufeinanderfolgende Aufrufe der Schutzfunktion <code>E2E_P07Protect</code> hinweg, wobei der enthaltene Sequenzzähler (<code>Counter</code>) pro geschützter Nachricht inkrementiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der C-Struktur für die E2E-Profil-7-Senderzustandsverwaltung. Softwarekomponenten und E2E-Wrapper müssen eine Instanz dieses Typs persistent im RAM vorhalten und als Ein-/Ausgangsparameter an die E2E-Schutzroutine übergeben, um die Sequenzzählung und Erkennung von Nachrichtenwiederholungen/Verlusten sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-06b53f8f6ed2f0be", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstruktur-Spezifikation der E2E-Bibliothek (AUTOSAR Adaptive / Classic Platform). Das Diagramm definiert den Zustandsdatentyp für den Schutzmechanismus des E2E-Profils 7 (<code>E2E Profile 7</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Strukturtyp:</p>\n<ul class=\"fig-list\"><li><code>«structure» E2E_P07Types::E2E_P07ProtectStateType</code>\n</li></ul>\n<p class=\"fig-p\">Attribute:</p>\n<ul class=\"fig-list\"><li><code>+ Counter: uint32</code>: Öffentliches Attribut zur Speicherung des 32-Bit-Sequenzzählers des Senders für nachfolgende Absicherungsoperationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne dynamische Ablauf- oder Zustandsübergangsdarstellung. Der Typ kapselt den Senderzustand über aufeinanderfolgende Aufrufe der Schutzfunktion <code>E2E_P07Protect</code> hinweg, wobei der enthaltene Sequenzzähler (<code>Counter</code>) pro geschützter Nachricht inkrementiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der C-Struktur für die E2E-Profil-7-Senderzustandsverwaltung. Softwarekomponenten und E2E-Wrapper müssen eine Instanz dieses Typs persistent im RAM vorhalten und als Ein-/Ausgangsparameter an die E2E-Schutzroutine übergeben, um die Sequenzzählung und Erkennung von Nachrichtenwiederholungen/Verlusten sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ecbaf97b32c9bc8b", "to": "FIG-360665a0f11f90fd", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Paketpfad im Typnamen: Entfernung des übergeordneten Namensraums <code>E2E::</code>, Typname von <code>E2E::E2E_P07Types::E2E_P07ProtectStateType</code> zu <code>E2E_P07Types::E2E_P07ProtectStateType</code> verkürzt.\n</li><li>Typattribut: Leerzeichen vor dem Doppelpunkt bei <code>+ Counter :uint32</code> entfernt (<code>+ Counter: uint32</code>).\n</li></ul>"}, {"from": "FIG-360665a0f11f90fd", "to": "FIG-06b53f8f6ed2f0be", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
